using System.Net;
using System.Net.Http.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Microsoft.EntityFrameworkCore;
using Npgsql;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class MeterApiTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>
{
    private static DateOnly Today=>DateOnly.FromDateTime(DateTime.UtcNow.AddHours(3));
    private static string Root(Guid p)=>$"/api/v1/properties/{p}/meters";
    private async Task<(Property P,string Actor,Unit U)> Seed(){var actor=Guid.NewGuid().ToString();var p=new Property("Meter "+actor,"City","District","Address",PropertyType.APARTMENT);var u=p.AddUnit("1",0,80);await factory.WithDb(async db=>{db.Add(p);db.Add(new PropertyMembership(p.Id,actor));await db.SaveChangesAsync();});return(p,actor,u);}
    private static async Task<MeterResponse> Create(HttpClient c,Guid p,Guid? unit=null){var r=await c.PostAsJsonAsync(Root(p),new CreateMeterRequest(Guid.NewGuid(),"Water","WATER",unit));Assert.Equal(HttpStatusCode.OK,r.StatusCode);return(await r.Content.ReadFromJsonAsync<MeterResponse>())!;}
    private static ReadingRequest Reading(DateOnly date,string value="100.123",long version=0)=>new(Guid.NewGuid(),date,value,"Reading reason",version);
    private static async Task<ReadingResponse> Save(HttpClient c,Guid p,Guid m,ReadingRequest request,Guid? r=null){var path=Root(p)+$"/{m}/readings";var response=r.HasValue?await c.PutAsJsonAsync(path+"/"+r,request):await c.PostAsJsonAsync(path,request);Assert.Equal(HttpStatusCode.OK,response.StatusCode);return(await response.Content.ReadFromJsonAsync<ReadingResponse>())!;}
    [PostgresFact] public async Task BaselineConsumptionCorrectionAndRetryPreserveHistory(){var x=await Seed();using var c=TestToken.Client(factory,x.Actor,"MANAGER");var m=await Create(c,x.P.Id,x.U.Id);var first=await Save(c,x.P.Id,m.Id,Reading(Today.AddDays(-2)));Assert.Null(first.Consumption);var request=Reading(Today,"110.456");var second=await Save(c,x.P.Id,m.Id,request);Assert.Equal("10.333",second.Consumption);var replay=await Save(c,x.P.Id,m.Id,request);Assert.True(replay.Replayed);Assert.Equal(second.Id,replay.Id);var correction=Reading(Today,"111.000",second.Version);var current=await Save(c,x.P.Id,m.Id,correction,second.Id);Assert.Equal("10.877",current.Consumption);Assert.Equal(2,current.Revisions.Count);Assert.Equal("110.456",current.Revisions[1].Value);Assert.Equal(2,current.Version);var oldRetry=await Save(c,x.P.Id,m.Id,request);Assert.Equal("111.000",oldRetry.Value);Assert.True(oldRetry.Replayed);await factory.WithDb(async db=>{var r=await db.MeterReadings.SingleAsync(r=>r.Id==second.Id);Assert.Equal(x.Actor,r.CreatedBy);Assert.Equal(first.Version,r.Version-1);Assert.Equal(3,await db.MeterReadingRevisions.CountAsync(r=>r.PropertyId==x.P.Id));await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE meter_reading_revisions SET value=0 WHERE reading_id={r.Id}"));});}
    [PostgresFact] public async Task BothNeighboursAndImmutableDateAreEnforced(){var x=await Seed();using var c=TestToken.Client(factory,x.Actor,"SUPER_ADMIN");var m=await Create(c,x.P.Id);await Save(c,x.P.Id,m.Id,Reading(Today.AddDays(-4),"100"));var last=await Save(c,x.P.Id,m.Id,Reading(Today,"200"));var path=Root(x.P.Id)+$"/{m.Id}/readings";foreach(var v in new[]{"99.999","200.001"})Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(path,Reading(Today.AddDays(-2),v))).StatusCode);var mid=await Save(c,x.P.Id,m.Id,Reading(Today.AddDays(-2),"150"));Assert.Equal("50.000",mid.Consumption);Assert.Equal(HttpStatusCode.Conflict,(await c.PutAsJsonAsync(path+"/"+mid.Id,Reading(mid.ReadingDate,"201",mid.Version))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.PutAsJsonAsync(path+"/"+last.Id,Reading(Today.AddDays(-1),"200",last.Version))).StatusCode);}
    [PostgresFact] public async Task ConcurrentMeterAndReadingReplayAreSingleAndChangedPayloadConflicts(){var x=await Seed();using var c=TestToken.Client(factory,x.Actor,"SUPER_ADMIN");var req=new CreateMeterRequest(Guid.NewGuid()," Unique ","GAS",null);var results=await Task.WhenAll(c.PostAsJsonAsync(Root(x.P.Id),req),c.PostAsJsonAsync(Root(x.P.Id),req));Assert.All(results,r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));var a=(await results[0].Content.ReadFromJsonAsync<MeterResponse>())!;var b=(await results[1].Content.ReadFromJsonAsync<MeterResponse>())!;Assert.Equal(a.Id,b.Id);Assert.NotEqual(a.Replayed,b.Replayed);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(Root(x.P.Id),req with{Name="Other"})).StatusCode);var rr=Reading(Today,"0");var path=Root(x.P.Id)+$"/{a.Id}/readings";var read=await Task.WhenAll(c.PostAsJsonAsync(path,rr),c.PostAsJsonAsync(path,rr));Assert.All(read,r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(path,rr with{Value="1"})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(path,Reading(Today,"0"))).StatusCode);}
    [PostgresTheory][InlineData("-1")][InlineData("1.0001")][InlineData("1e2")][InlineData("1,23")][InlineData("1000000000")]
    public async Task InvalidIndexesAreCodedAndAtomic(string v){var x=await Seed();using var c=TestToken.Client(factory,x.Actor,"MANAGER");var m=await Create(c,x.P.Id);var response=await c.PostAsJsonAsync(Root(x.P.Id)+$"/{m.Id}/readings",Reading(Today,v));Assert.Equal(HttpStatusCode.BadRequest,response.StatusCode);Assert.Contains("BF_READING_INVALID",await response.Content.ReadAsStringAsync());await factory.WithDb(async db=>Assert.False(await db.MeterReadings.AnyAsync(r=>r.PropertyId==x.P.Id)));}
    [PostgresFact] public async Task ScopeJwtRolesAndAccountantReadOnlyAreEnforced(){var x=await Seed();var other=await Seed();using var admin=TestToken.Client(factory,x.Actor,"SUPER_ADMIN");var m=await Create(admin,x.P.Id);using var anon=factory.CreateClient();using var outsider=TestToken.Client(factory,other.Actor,"MANAGER");using var resident=TestToken.Client(factory,x.Actor,"RESIDENT");using var accountant=TestToken.Client(factory,x.Actor,"ACCOUNTANT");using var malformed=factory.CreateClient();malformed.DefaultRequestHeaders.Authorization=new("Bearer","not-a-jwt");foreach(var suffix in new[]{"",$"/{m.Id}/readings"}){Assert.Equal(HttpStatusCode.Unauthorized,(await anon.GetAsync(Root(x.P.Id)+suffix)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await malformed.GetAsync(Root(x.P.Id)+suffix)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await outsider.GetAsync(Root(x.P.Id)+suffix)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await resident.GetAsync(Root(x.P.Id)+suffix)).StatusCode);Assert.Equal(HttpStatusCode.OK,(await accountant.GetAsync(Root(x.P.Id)+suffix)).StatusCode);}Assert.Equal(HttpStatusCode.Forbidden,(await accountant.PostAsJsonAsync(Root(x.P.Id),new CreateMeterRequest(Guid.NewGuid(),"Gas","GAS",null))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await accountant.PostAsJsonAsync(Root(x.P.Id)+$"/{m.Id}/readings",Reading(Today))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await admin.PostAsJsonAsync(Root(x.P.Id),new CreateMeterRequest(Guid.NewGuid(),"Foreign","WATER",other.U.Id))).StatusCode);}
    [PostgresFact] public async Task StaleCorrectionAndInactiveParentAreRejected(){var x=await Seed();using var c=TestToken.Client(factory,x.Actor,"SUPER_ADMIN");var m=await Create(c,x.P.Id);var r=await Save(c,x.P.Id,m.Id,Reading(Today));Assert.Equal(HttpStatusCode.Conflict,(await c.PutAsJsonAsync(Root(x.P.Id)+$"/{m.Id}/readings/{r.Id}",Reading(Today,"1",999))).StatusCode);await factory.WithDb(async db=>{(await db.Properties.SingleAsync(p=>p.Id==x.P.Id)).SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Conflict,(await c.PostAsJsonAsync(Root(x.P.Id),new CreateMeterRequest(Guid.NewGuid(),"New","GAS",null))).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.GetAsync(Root(x.P.Id))).StatusCode);}
}
